    "id": "spl-soul-cage",
    "name": "Jaula de Almas",
    "nameEn": "Soul Cage",
    "level": 6,
    "school": "Nigromancia",
    "castingTime": "1 reacción, cuando un humanoide que puedas ver a 60 pies de ti muere",
    "range": "60 pies",
